6: /// RAII guard that enables hardware FTZ/DAZ upon creation and restores the previous state on drop.
7: #[derive(Debug)]
8: pub struct ScopedFtzDaz {
9:     #[cfg(target_arch = "x86_64")]
10:     prev_mxcsr: u32,
11:     #[cfg(target_arch = "aarch64")]
12:     prev_fpcr: u64,
