18: #[inline]
19: unsafe fn get_mxcsr() -> u32 {
20:     let mut mxcsr: u32 = 0;
21:     unsafe {
22:         core::arch::asm!("stmxcsr [{}]", in(reg) &mut mxcsr, options(nostack, preserves_flags));
23:     }
24:     mxcsr
25: }
26: 
