29: unsafe fn set_mxcsr(val: u32) {
30:     let mxcsr = val;
31:     unsafe {
32:         core::arch::asm!("ldmxcsr [{}]", in(reg) &mxcsr, options(nostack, preserves_flags));
33:     }
34: }
