37:     /// Enables FTZ and DAZ on the current thread, returning an RAII guard that restores previous flags on drop.
38:     pub fn new() -> Self {
39:         #[cfg(target_arch = "x86_64")]
40:         {
41:             // Bit 15: FTZ (Flush-to-zero)
42:             // Bit 6:  DAZ (Denormals-are-zero)
43:             const FTZ_DAZ_MASK: u32 = (1 << 15) | (1 << 6);
44:             let prev_mxcsr = unsafe { get_mxcsr() };
45:             unsafe { set_mxcsr(prev_mxcsr | FTZ_DAZ_MASK) };
46:             Self { prev_mxcsr }
47:         }
48: 
49:         #[cfg(target_arch = "aarch64")]
50:         {
51:             // Bit 24: FZ (Flush-to-zero)
52:             const FZ_MASK: u64 = 1 << 24;
53:             let mut prev_fpcr: u64;
54:             unsafe {
55:                 core::arch::asm!("mrs {}, fpcr", out(reg) prev_fpcr);
56:                 core::arch::asm!("msr fpcr, {}", in(reg) (prev_fpcr | FZ_MASK));
57:             }
58:             Self { prev_fpcr }
59:         }
60: 
61:         #[cfg(not(any(target_arch = "x86_64", target_arch = "aarch64")))]
62:         {
63:             Self { _unused: () }
64:         }
65:     }
