68:     pub fn is_active() -> bool {
69:         #[cfg(target_arch = "x86_64")]
70:         {
71:             const FTZ_DAZ_MASK: u32 = (1 << 15) | (1 << 6);
72:             let mxcsr = unsafe { get_mxcsr() };
